									class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
									@click="resetTanggal"
								>
									Reset
								</button>
								<button
									type="button"
									class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
									@click="showTanggal = false"
								>
									Selesai
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { createResource } from 'frappe-ui'
import { angka, rentang, statusBadge, tanggal } from '../data/cutiStatus'
import { NAVIGATION_ORIGIN, withNavigationOrigin } from '../data/navigationOrigin'
import { useBackNavigation } from '../composables/useBackNavigation'
import { useListPersistence } from '../composables/useListPersistence'

// Antrean & riwayat keputusan cuti untuk atasan, HR, dan Ketua. Cuti milik
// sendiri tidak pernah tampil di sini; tempatnya di menu Cuti. Keputusan
// diambil di halaman detail cuti, yang juga memuat lembar pembagian kelebihan
// milik Ketua. Urutkan & Filter mengikuti list view portal lainnya.
const { backTarget, backLabel } = useBackNavigation({ name: 'Home' }, 'Home')
const listPersistence = useListPersistence('ApprovalCuti')

const PER_HALAMAN = 20

// Diproses = bisa Anda putuskan sekarang; Menunggu = sedang di tahap orang lain.
const KARTU = [
	{
		key: 'diproses',
		label: 'Diproses',
		bg: 'bg-ui-surface-amber-50',
		teks: 'text-ui-ink-amber-700',
		angka: 'text-ui-ink-amber-900',
		kosong: 'Tidak ada cuti yang perlu Anda proses.',
	},
	{
		key: 'menunggu',
		label: 'Menunggu',
		bg: 'bg-ui-surface-sky-50',
		teks: 'text-ui-ink-sky-700',
		angka: 'text-ui-ink-sky-900',
		kosong: 'Tidak ada cuti yang sedang menunggu di tahap lain.',
	},
	{
		key: 'disetujui',
		label: 'Disetujui',
		bg: 'bg-ui-surface-green-50',
		teks: 'text-ui-ink-green-700',
		angka: 'text-ui-ink-green-800',
		kosong: 'Belum ada cuti yang disetujui.',
	},
	{
		key: 'ditolak',
		label: 'Ditolak',
		bg: 'bg-ui-surface-red-50',
		teks: 'text-ui-ink-red-700',
		angka: 'text-ui-ink-red-900',
		kosong: 'Belum ada cuti yang ditolak.',
	},
]

// Daftar ini harus ada juga di SORT_FIELDS sisi server — di sana yang menolak
// kolom di luar daftar putih.
const SORT_FIELDS = [
	{ key: 'modified', label: 'Terakhir Diubah' },
	{ key: 'from_date', label: 'Tanggal Mulai' },
	{ key: 'to_date', label: 'Tanggal Selesai' },
	{ key: 'total_leave_days', label: 'Lama Cuti' },
	{ key: 'employee_name', label: 'Nama Karyawan' },
	{ key: 'leave_type', label: 'Jenis Cuti' },
	{ key: 'creation', label: 'Dibuat' },
]

const SARINGAN_KOSONG = { cari: '', leave_type: [], dari: '', sampai: '' }

const kategori = ref('diproses')
const rows = ref([])
const ringkasan = ref({ leave_type: [] })
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

const showSort = ref(false)
const showFilter = ref(false)
const showJenis = ref(false)
const showTanggal = ref(false)
const sortField = ref('modified')
const sortDir = ref('desc')
const draftSortField = ref('modified')
const draftSortDir = ref('desc')
// `terpakai` yang dikirim ke server; `draft` yang sedang diubah di panel.
const terpakai = reactive({ ...SARINGAN_KOSONG, leave_type: [] })
const draft = reactive({ ...SARINGAN_KOSONG, leave_type: [] })

const jumlahSaringan = computed(() => {
	let n = 0
	if (terpakai.cari.trim()) n++
	if (terpakai.leave_type.length) n++
	if (terpakai.dari || terpakai.sampai) n++
	return n
})

const teksKosong = computed(() =>
	jumlahSaringan.value
		? 'Tidak ada yang cocok dengan filter ini.'
		: KARTU.find((k) => k.key === kategori.value)?.kosong
)

// Sub-sheet pilih banyak memakai markup yang sama dengan halaman Cuti.
const pilihanSub = computed(() => ringkasan.value.leave_type || [])
const arraySub = computed(() => draft.leave_type)
function tutupSub() {
	showJenis.value = false
}
function resetTanggal() {
	draft.dari = ''
	draft.sampai = ''
}
function pilihGanda(arr, nilai) {
	const i = arr.indexOf(nilai)
	if (i === -1) arr.push(nilai)
	else arr.splice(i, 1)
}
function ringkas(arr) {
	if (!arr.length) return ''
	return arr.length === 1 ? arr[0] : `${arr[0]} +${arr.length - 1}`
}
const ringkasJenis = computed(() => ringkas(draft.leave_type))
const ringkasTanggal = computed(() => {
	if (draft.dari && draft.sampai) return `${tanggal(draft.dari)} – ${tanggal(draft.sampai)}`
	if (draft.dari) return `Sejak ${tanggal(draft.dari)}`
	if (draft.sampai) return `Sampai ${tanggal(draft.sampai)}`
	return ''
})

function inisial(nama) {
	return String(nama || '?')
		.split(/\s+/)
		.slice(0, 2)
		.map((w) => w[0] || '')
		.join('')
		.toUpperCase()
}

function keDetail(row) {
	return withNavigationOrigin(
		{ name: 'CutiDetail', params: { name: row.name } },
		NAVIGATION_ORIGIN.APPROVAL_CUTI
	)
}

function saring() {
	const p = {}
	if (terpakai.cari.trim()) p.q = terpakai.cari.trim()
	if (terpakai.leave_type.length) p.leave_type = JSON.stringify(terpakai.leave_type)
	if (terpakai.dari) p.dari = terpakai.dari
	if (terpakai.sampai) p.sampai = terpakai.sampai
	return p
}

const list = createResource({
	url: 'juragan.api.portal.cuti.get_approval',
	auto: false,
	makeParams() {
		return {
			...saring(),
			kategori: kategori.value,
			sort_field: sortField.value,
			sort_dir: sortDir.value,
			limit: PER_HALAMAN,
			start: start.value,
		}
	},
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

const ringkasanRes = createResource({
	url: 'juragan.api.portal.cuti.get_ringkasan_approval',
	auto: false,
	makeParams: saring,
	onSuccess(data) {
		if (data) ringkasan.value = data
	},
	// Handler wajib ada meski kosong: tanpa onError, galat yang sama muncul dua
	// kali (dari resource dan dari handler global).
	onError() {},
})

function reload() {
	listPersistence.writeSession({ kategori: kategori.value, filters: terpakai })
	error.value = ''
	start.value = 0
	loading.value = true
	list.fetch()
	ringkasanRes.fetch()
}

function muatLagi() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

function pilihKategori(k) {
	if (kategori.value === k) return
	kategori.value = k
	reload()
}

function openSort() {
	draftSortField.value = sortField.value
	draftSortDir.value = sortDir.value
	showSort.value = true
}
function applySort() {
	sortField.value = draftSortField.value
	sortDir.value = draftSortDir.value
	listPersistence.writePreferences({ sortField: sortField.value, sortDir: sortDir.value })
	showSort.value = false
	reload()
}

function openFilter() {
	Object.assign(draft, { ...terpakai, leave_type: [...terpakai.leave_type] })
	showFilter.value = true
}
function applyFilter() {
	Object.assign(terpakai, { ...draft, leave_type: [...draft.leave_type] })
	showFilter.value = false
	reload()
}
function clearFilter() {
	Object.assign(draft, { ...SARINGAN_KOSONG, leave_type: [] })
	Object.assign(terpakai, { ...SARINGAN_KOSONG, leave_type: [] })
	showFilter.value = false
	reload()
}

onMounted(() => {
	// Kartu & saringan dibawa pulang dari halaman detail; urutan diingat
	// sebagai preferensi, sama seperti list view lain.
	const saved = listPersistence.readSession({ kategori: 'diproses', filters: SARINGAN_KOSONG })
	if (KARTU.some((k) => k.key === saved.kategori)) kategori.value = saved.kategori
	const f = { ...SARINGAN_KOSONG, ...(saved.filters || {}) }
	Object.assign(terpakai, {
		cari: String(f.cari || ''),
		leave_type: Array.isArray(f.leave_type) ? f.leave_type : [],
		dari: f.dari || '',
		sampai: f.sampai || '',
	})
	const prefs = listPersistence.readPreferences({ sortField: 'modified', sortDir: 'desc' })
	if (SORT_FIELDS.some((x) => x.key === prefs.sortField)) sortField.value = prefs.sortField
	if (['asc', 'desc'].includes(prefs.sortDir)) sortDir.value = prefs.sortDir
	reload()
})
</script>

<style>
/* Cermin dari .dp-field di Data Pengajuan — baris field pada bottom-sheet
   Filter: border melingkupi ikon + isian, abu-abu default, biru saat fokus.
   Sengaja diberi awalan sendiri agar halaman ini tidak bergantung pada style
   milik komponen lain yang kebetulan sudah termuat. */
.ct-field {
	@apply flex w-full items-center gap-3 rounded-2xl border border-ui-line-gray-300 px-4 py-3.5 transition;
}
.ct-field-input {
	@apply w-full border-0 bg-transparent p-0 text-ui-ink-gray-800 placeholder-ui-ink-gray-500 caret-primary outline-none focus:ring-0;
}
.ct-field-ic {
	@apply h-5 w-5 shrink-0 text-ui-ink-gray-500;
}
.ct-field-chev {
	@apply h-4 w-4 shrink-0 text-ui-ink-gray-500;
}
</style>
